package authn_test

import (
	"context"
	"crypto/ed25519"
	"crypto/rand"
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"strings"
	"testing"

	"github.com/egdaemon/eg/authn"
	"github.com/egdaemon/eg/internal/httpx"
	"github.com/stretchr/testify/require"
	"golang.org/x/crypto/ssh"
	"golang.org/x/oauth2"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestAutoRefreshTokenState(t *testing.T) {
	t.Run("returns existing token from environment", func(t *testing.T) {
		t.Setenv("EG_SESSION_TOKEN", "existing-refresh-token")

		_, priv, err := ed25519.GenerateKey(rand.Reader)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)

		tok, err := authn.AutoRefreshTokenState(t.Context(), signer, "any-state")
		require.NoError(t, err)
		require.Equal(t, "BEARER", tok.TokenType)
		require.Equal(t, "existing-refresh-token", tok.RefreshToken)
	})

	t.Run("reports missing http client when no token in environment", func(t *testing.T) {
		os.Unsetenv("EG_SESSION_TOKEN")

		_, priv, err := ed25519.GenerateKey(rand.Reader)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)

		_, err = authn.AutoRefreshTokenState(context.Background(), signer, "state")
		require.ErrorContains(t, err, "missing http client")
	})

	t.Run("retrieves and persists token via oauth flow", func(t *testing.T) {
		os.Unsetenv("EG_SESSION_TOKEN")

		_, priv, err := ed25519.GenerateKey(rand.Reader)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)

		mux := http.NewServeMux()
		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
			switch {
			case strings.HasSuffix(r.URL.Path, "/oauth2/ssh/auth"):
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(fmt.Sprintf(`{"code":%q,"state":%q}`, "test-auth-code", "test-state")))
			case strings.HasSuffix(r.URL.Path, "/oauth2/ssh/token"):
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"access_token":"access-token-value","refresh_token":"refresh-token-value","token_type":"Bearer","expires_in":3600}`))
			default:
				w.WriteHeader(http.StatusNotFound)
			}
		})

		srv := httptest.NewServer(mux)
		t.Cleanup(srv.Close)

		dst, err := url.Parse(srv.URL)
		require.NoError(t, err)
		rt := httpx.RewriteHostTransport(dst, http.DefaultTransport)
		chttp := &http.Client{Transport: rt}

		ctx := context.WithValue(t.Context(), oauth2.HTTPClient, chttp)

		tok, err := authn.AutoRefreshTokenState(ctx, signer, "test-state")
		require.NoError(t, err)
		require.Equal(t, "access-token-value", tok.AccessToken)
		require.Equal(t, "refresh-token-value", tok.RefreshToken)

		got, ok := os.LookupEnv("EG_SESSION_TOKEN")
		require.True(t, ok)
		require.Equal(t, "refresh-token-value", got)
	})

	t.Run("reports state mismatch from server", func(t *testing.T) {
		os.Unsetenv("EG_SESSION_TOKEN")

		_, priv, err := ed25519.GenerateKey(rand.Reader)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)

		mux := http.NewServeMux()
		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
			if strings.HasSuffix(r.URL.Path, "/oauth2/ssh/auth") {
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"code":"test-auth-code","state":"different-state"}`))
			} else {
				w.WriteHeader(http.StatusNotFound)
			}
		})

		srv := httptest.NewServer(mux)
		t.Cleanup(srv.Close)

		dst, err := url.Parse(srv.URL)
		require.NoError(t, err)
		rt := httpx.RewriteHostTransport(dst, http.DefaultTransport)
		chttp := &http.Client{Transport: rt}

		ctx := context.WithValue(t.Context(), oauth2.HTTPClient, chttp)

		_, err = authn.AutoRefreshTokenState(ctx, signer, "expected-state")
		require.ErrorContains(t, err, "mismatch oauth state")
	})

	t.Run("reports error when token exchange fails", func(t *testing.T) {
		os.Unsetenv("EG_SESSION_TOKEN")

		_, priv, err := ed25519.GenerateKey(rand.Reader)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)

		mux := http.NewServeMux()
		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
			switch {
			case strings.HasSuffix(r.URL.Path, "/oauth2/ssh/auth"):
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"code":"test-auth-code","state":"test-state"}`))
			case strings.HasSuffix(r.URL.Path, "/oauth2/ssh/token"):
				w.WriteHeader(http.StatusInternalServerError)
				_, _ = w.Write([]byte(`{"error":"server_error"}`))
			default:
				w.WriteHeader(http.StatusNotFound)
			}
		})

		srv := httptest.NewServer(mux)
		t.Cleanup(srv.Close)

		dst, err := url.Parse(srv.URL)
		require.NoError(t, err)
		rt := httpx.RewriteHostTransport(dst, http.DefaultTransport)
		chttp := &http.Client{Transport: rt}

		ctx := context.WithValue(t.Context(), oauth2.HTTPClient, chttp)

		_, err = authn.AutoRefreshTokenState(ctx, signer, "test-state")
		require.Error(t, err)
	})
}
